import{_ as t}from"./chunks/webmcp.AtPcCTXa.js";import{_ as o,o as a,c as r,a2 as n}from"./chunks/framework.CfwCq2QB.js";const g=JSON.parse('{"title":"Page tools (WebMCP)","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/webmcp.md","filePath":"en/features/webmcp.md"}'),s={name:"en/features/webmcp.md"};function i(l,e,d,u,h,p){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="page-tools-webmcp" tabindex="-1">Page tools (WebMCP) <a class="header-anchor" href="#page-tools-webmcp" aria-label="Permalink to &quot;Page tools (WebMCP)&quot;">​</a></h1><p>In one line: DevGo lists the tools a page registers through WebMCP (iframes included) and the AI can call them to get things done. The side panel&#39;s &quot;Page tools&quot; page shows each tool&#39;s description and lets you run it manually — handy for debugging your own WebMCP implementation.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><p>WebMCP is currently a Chrome experiment:</p><ol><li>Use <strong>Chrome 150 or later</strong></li><li>Open <code>chrome://flags</code>, search for &quot;<strong>WebMCP for testing</strong>&quot;, and enable it</li><li>Restart the browser</li></ol><p>Without it, the &quot;View tools&quot; button on the popup&#39;s Features page is disabled with an explanation. Firefox isn&#39;t supported for now.</p><h2 id="using-it" tabindex="-1">Using it <a class="header-anchor" href="#using-it" aria-label="Permalink to &quot;Using it&quot;">​</a></h2><p>Open a page that provides tools and switch the side panel to the &quot;Page tools&quot; page:</p><ul><li>Each tool is a card: name, a <strong>Read-only</strong> or <strong>May modify data</strong> badge (iframe tools are marked), and a description</li><li>Expand a card to fill in arguments from the schema-generated template, click &quot;Run&quot;, and the result or error appears below</li><li>The header shows the tool count, with &quot;Check again&quot; on the right (single-page apps can register / unregister tools at any time)</li><li>Four states each get their own explainer: WebMCP off in the browser, page unreadable, no tools, checking</li></ul><p>The easier path: describe what you want in Chat — &quot;search for a red T-shirt&quot; — and the AI calls the tools itself.</p><img src="'+t+'" alt="The side panel&#39;s Page tools page: three tool cards from a demo shop with read-only / may-modify badges; search_products has been run and returned JSON" style="width:40%;display:block;margin-left:auto;margin-right:auto;"><p><em>The &quot;Page tools&quot; page: tool cards with Read-only / May modify data badges; search_products has been run and returned results.</em></p><h2 id="confirm-before-running" tabindex="-1">Confirm before running <a class="header-anchor" href="#confirm-before-running" aria-label="Permalink to &quot;Confirm before running&quot;">​</a></h2><p>Tools provided by pages and <strong>not declared read-only</strong> (they may submit forms, place orders, etc.) show a confirmation card before running — &quot;Allow&quot; or &quot;Reject&quot;. This protection is on by default and can be turned off under Settings → AI assistant (not recommended).</p><h2 id="for-web-developers" tabindex="-1">For web developers <a class="header-anchor" href="#for-web-developers" aria-label="Permalink to &quot;For web developers&quot;">​</a></h2><p>Register tools via <code>document.modelContext</code> and DevGo discovers them automatically; argument schemas are used to generate the fill-in template. Running tools manually on the &quot;Page tools&quot; page is the quickest way to debug your WebMCP implementation — no glue code required.</p>',16)])])}const b=o(s,[["render",i]]);export{g as __pageData,b as default};
